from itertools import combinations
from typing import FrozenSet, List, Set, Tuple

Family = Set[FrozenSet[int]]


def is_union_closed(family: Family) -> bool:
    return all((a | b) in family for a in family for b in family)


def degree(family: Family, x: int) -> int:
    return sum(1 for a in family if x in a)


def singleton_injection(family: Family, a: int) -> List[Tuple[FrozenSet[int], FrozenSet[int]]]:
    """Witness that {a} in F implies 'a' is abundant: the injection A -> A u {a}."""
    assert frozenset({a}) in family and is_union_closed(family)
    avoid = [A for A in family if a not in A]
    pairs = [(A, A | {a}) for A in avoid]
    images = [img for _, img in pairs]
    assert len(set(images)) == len(images)              # injective
    assert all(img in family for img in images)          # lands in F
    return pairs


def demo() -> None:
    F: Family = {frozenset(), frozenset({1}), frozenset({2}),
                 frozenset({1, 2}), frozenset({1, 2, 3}), frozenset({2, 3})}
    # close under union
    changed = True
    while changed:
        changed = False
        for a in list(F):
            for b in list(F):
                if (a | b) not in F:
                    F.add(a | b); changed = True
    pairs = singleton_injection(F, 1)
    print(f"|F| = {len(F)}, degree(1) = {degree(F, 1)}")
    print(f"2*degree(1) = {2 * degree(F, 1)} >= |F| = {len(F)}: "
          f"{2 * degree(F, 1) >= len(F)}")
    for A, img in pairs:
        print(f"  {set(A)!s:<15} -> {set(img)}")


if __name__ == "__main__":
    demo()

from itertools import combinations
from typing import FrozenSet, List, Optional, Set, Tuple

Family = Set[FrozenSet[int]]


def powerset(n: int) -> List[FrozenSet[int]]:
    xs = list(range(n))
    return [frozenset(c) for r in range(n + 1) for c in combinations(xs, r)]


def is_union_closed(F: Family) -> bool:
    return all((a | b) in F for a in F for b in F)


def abundant_element(F: Family) -> Optional[int]:
    elems = set().union(*F) if F else set()
    for x in sorted(elems):
        if 2 * sum(1 for A in F if x in A) >= len(F):
            return x
    return None


def verify_fin_n(n: int) -> Tuple[int, int]:
    """Exhaustively verify Frankl for the universe {0,...,n-1}."""
    sets = powerset(n)
    checked = counter = 0
    for mask in range(1 << len(sets)):
        F: Family = {sets[i] for i in range(len(sets)) if mask & (1 << i)}
        if not F or not any(len(A) for A in F) or not is_union_closed(F):
            continue
        checked += 1
        if abundant_element(F) is None:
            counter += 1
    return checked, counter


def demo() -> None:
    for n in range(4):
        checked, cex = verify_fin_n(n)
        print(f"Fin {n}: {checked:>4} union-closed families, counterexamples = {cex}")


if __name__ == "__main__":
    demo()

from itertools import combinations
from typing import List, Tuple


def subset_sizes_total(n: int) -> int:
    return sum(len(c) for r in range(n + 1) for c in combinations(range(n), r))


def reimer_check(n: int) -> Tuple[int, int, float]:
    total = subset_sizes_total(n)
    num = 2 ** n
    return 2 * total, n * num, total / num


def demo() -> None:
    print(" n | 2*sum|A| |  n*2^n | avg | n/2")
    for n in range(9):
        lhs, rhs, avg = reimer_check(n)
        assert lhs == rhs, "reimer_tight_cube failed!"
        print(f" {n} | {lhs:>7} | {rhs:>6} | {avg:>3.1f} | {n/2:>3.1f}")
    print("All equalities 2*sum|A| == n*2^n verified.")


if __name__ == "__main__":
    demo()

